CREATE TABLE iview_production_rule (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, template_id BIGINT NOT NULL, quantity_point_id BIGINT NOT NULL, qualified_point_id BIGINT, enabled BOOLEAN NOT NULL DEFAULT TRUE, rule_version BIGINT NOT NULL DEFAULT 1, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE iview_production_checkpoint (device_id BIGINT NOT NULL, point_id BIGINT NOT NULL, quantity BIGINT NOT NULL, observed_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(device_id,point_id));
CREATE TABLE iview_production_record (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, device_id BIGINT NOT NULL, quantity BIGINT NOT NULL, qualified_quantity BIGINT NOT NULL, start_time TIMESTAMP WITH TIME ZONE NOT NULL, end_time TIMESTAMP WITH TIME ZONE NOT NULL, rule_version VARCHAR(100) NOT NULL, attrs_json TEXT NOT NULL DEFAULT '{}', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uk_production_window UNIQUE(device_id,start_time,end_time));
CREATE INDEX idx_iview_production_record_time ON iview_production_record(device_id,end_time);
